#include <security/policy/policy_engine.hpp>
namespace rebuntu::policy { Decision PolicyEngine::evaluate(const platform::v0040::ChangePlan&p,const Context&c)const{Decision d;if(p.privileged&&!c.elevated){d.reasons.push_back("elevation required");return d;}if(p.risk==platform::v0040::Risk::destructive){d.confirmation=true;if(!c.interactive){d.reasons.push_back("destructive operation requires interactive operator");return d;}}if(p.domain=="secrets"&&!c.capabilities.count("secrets.write")){d.reasons.push_back("secrets.write capability required");return d;}d.allowed=true;d.reasons.push_back("policy satisfied");return d;} }
